 private void chooseBusStop(){if(snapshot==null||snapshot.busStops.isEmpty())return;final ArrayList<JourneyData.Station> stops=new ArrayList<JourneyData.Station>(snapshot.busStops);final Dialog d=dialog("Hat durağı seç");LinearLayout content=(LinearLayout)d.findViewById(7201);final EditText search=new EditText(this);search.setSingleLine(true);search.setTextSize(14);search.setHint("Durak adı veya kodu");content.addView(search,new LinearLayout.LayoutParams(-1,dp(44)));ScrollView scroll=new ScrollView(this);final LinearLayout list=new LinearLayout(this);list.setOrientation(1);scroll.addView(list);content.addView(scroll,new LinearLayout.LayoutParams(-1,dp(compact?170:270)));final Runnable render=new Runnable(){public void run(){list.removeAllViews();String query=search.getText().toString().trim().toLowerCase(new Locale("tr","TR"));for(final JourneyData.Station stop:stops)if((stop.code+" "+stop.name).toLowerCase(new Locale("tr","TR")).contains(query)){TextView row=text(stop.code+" · "+stop.name,14,INK);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(6),0,dp(6),0);list.addView(row,new LinearLayout.LayoutParams(-1,dp(48)));row.setOnClickListener(new View.OnClickListener(){public void onClick(View v){d.dismiss();stopTracking();stopInput.setText(stop.code);beginTracking();}});}}};search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){render.run();}public void afterTextChanged(android.text.Editable s){}});render.run();d.show();}
 private String directionLabel(){String direction=getPreferences(0).getString("track-direction:"+city,"");return direction.equals("G")?"Gidiş":direction.equals("D")?"Dönüş":"İki yön";}
 private void chooseDirection(){final Dialog d=dialog("İETT yönü");LinearLayout content=(LinearLayout)d.findViewById(7201);String[] labels={"İki yön","Gidiş (G)","Dönüş (D)"};final String[] codes={"","G","D"};for(int i=0;i<labels.length;i++){final int which=i;LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(48));lp.bottomMargin=dp(6);content.addView(button(labels[i],false,new View.OnClickListener(){public void onClick(View v){d.dismiss();boolean restart=tracking;stopTracking();getPreferences(0).edit().putString("track-direction:"+city,codes[which]).commit();snapshot=null;build();if(restart)beginTracking();}}),lp);}d.show();}
 private void centerCity(){if(map!=null)map.center(CityRegistry.get(city).lat,CityRegistry.get(city).lon,12);}
 private void beginTracking(){String stop=stopInput.getText().toString().trim(),line=lineInput.getText().toString().trim();if(!stop.matches(city==0?"[0-9]{5}":"[0-9]{1,8}")||!line.matches("[A-Za-z0-9ÇĞİÖŞÜçğıöşü-]{0,16}")){Toast.makeText(this,"Geçerli durak ve hat kodu gir",Toast.LENGTH_LONG).show();return;}if(queryCity!=city||!queryStop.equals(stop)||!queryLine.equals(line)){queryCity=city;queryStop=stop;queryLine=line;selectedStop=null;liveRoute=null;routeTicket++;snapshot=null;map.route(null);map.positions(new ArrayList<JourneyData.Vehicle>(),false);map.selectedStop(null);updateMapBadge();renderSnapshot();}resolveStop(stop);getPreferences(0).edit().putString("track-stop:"+city,stop).putString("track-line:"+city,line).commit();tracking=true;fitNext=true;start.setText("Durdur");root.requestFocus();try{((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(stopInput.getWindowToken(),0);}catch(Exception ignored){}refresh();}
 private final Runnable poll=new Runnable(){public void run(){if(tracking&&resumed&&screen==0)refresh();}};
 private void refresh(){if(refreshing||destroyed||screen!=0)return;if(request!=null&&request.isAlive()){if(tracking&&resumed)handler.postDelayed(poll,1000);return;}refreshing=true;final int token=generation,selected=city;final String stop=getPreferences(0).getString("track-stop:"+city,defaultStop()),line=getPreferences(0).getString("track-line:"+city,defaultLine());status.setText(snapshot==null?"Canlı konumlar alınıyor…":"Yenileniyor · son konumlar gösteriliyor");request=new Thread(new Runnable(){public void run(){JourneyData.Snapshot next=null;String error=null;try{next=TrackingClient.query(selected,stop,line,getPreferences(0).getString("track-direction:"+selected,""));}catch(Exception e){error=e.getMessage();}final JourneyData.Snapshot data=next;final String failure=error;handler.post(new Runnable(){public void run(){refreshing=false;if(destroyed||token!=generation||!resumed)return;if(data!=null){snapshot=data;if(liveRoute==null)map.busStops(data.busStops);map.positions(data.mapVehicles(),fitNext);fitNext=false;renderSnapshot();}else status.setText(snapshot==null?"Bağlantı kurulamadı · yeniden dene":"Yenilenemedi · önceki konumlar gösteriliyor");if(tracking)handler.postDelayed(poll,failure==null&&data!=null?data.suggestedRefreshMillis:30000);}});}});request.start();}
 private void stopTracking(){tracking=false;generation++;handler.removeCallbacks(poll);if(request!=null)request.interrupt();refreshing=false;}
 private void updateMapBadge(){if(mapBadge!=null)mapBadge.setText(liveRoute==null?(city==1?"Yön: "+directionLabel()+"  ⌄":"Otobüs GPS konumları"):liveRoute.code+" · "+(liveRoute.schematic?"Şematik rota":"Rota")+"  ×");}
 private void resolveStop(final String code){final int ticket=++stopTicket,chosen=city;final OsmMapView target=map;new Thread(new Runnable(){public void run(){JourneyData.Station found=null;try{found=StopResolver.resolve(TransitActivity.this,chosen,code);}catch(Exception ignored){}final JourneyData.Station stop=found;handler.post(new Runnable(){public void run(){if(destroyed||ticket!=stopTicket||chosen!=city||map!=target||screen!=0||!stopInput.getText().toString().trim().equals(code))return;selectedStop=stop;map.selectedStop(stop);if(stop!=null)map.fitContent();else Toast.makeText(TransitActivity.this,code+" durağının koordinatı bulunamadı",Toast.LENGTH_SHORT).show();}});}}).start();}
 private void showLiveRoute(final String code,final String variant,final String name){final int ticket=++routeTicket,chosen=city;final OsmMapView target=map;mapBadge.setText(code+" · Rota alınıyor…");new Thread(new Runnable(){public void run(){JourneyData.Route loaded=null;CatalogStore store=new CatalogStore(TransitActivity.this);try{CatalogStore.Item item=null;for(CatalogStore.Item candidate:store.page(chosen,0,code,0).items)if(candidate.code.equalsIgnoreCase(code)){if(item==null)item=candidate;if(variant.length()>0&&variant.equals(store.external(candidate.id))){item=candidate;break;}}if(item==null){item=new CatalogStore.Item();item.code=code;item.name=name;item.type="Otobüs";}loaded=RouteRepository.load(TransitActivity.this,chosen,item,false,variant);}catch(Exception ignored){}finally{store.close();}final JourneyData.Route data=loaded;handler.post(new Runnable(){public void run(){if(destroyed||ticket!=routeTicket||city!=chosen||map!=target||screen!=0)return;if(data!=null&&!data.parts.isEmpty()){liveRoute=data;map.route(data);map.fitContent();updateMapBadge();}else{updateMapBadge();Toast.makeText(TransitActivity.this,"Bu hattın rota konumları alınamadı",Toast.LENGTH_LONG).show();}}});}}).start();}
 private void renderSnapshot(){if(bottomRows==null)return;bottomRows.removeAllViews();if(snapshot==null){TextView empty=text("Durağını seç. Otobüsün haritada görünsün.",14,MUTED);empty.setPadding(0,dp(8),0,0);bottomRows.addView(empty);return;}SimpleDateFormat f=new SimpleDateFormat("HH:mm:ss",Locale.US);f.setTimeZone(TimeZone.getTimeZone("GMT+03:00"));status.setText(city==1?snapshot.rows.size()+" varış · "+snapshot.positionCount()+" GPS · "+f.format(new Date(snapshot.receivedAt)):snapshot.positionCount()+" kaynak konumu · alındı "+f.format(new Date(snapshot.receivedAt)));for(int i=0;i<snapshot.rows.size();i++){final JourneyData.Vehicle v=snapshot.rows.get(i);LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);TextView code=text(v.line,16,BLUE);code.setGravity(Gravity.CENTER_VERTICAL);code.setContentDescription(v.line+" hattının rotasını göster");code.setOnClickListener(new View.OnClickListener(){public void onClick(View view){showLiveRoute(v.line,v.routeCode,v.name);}});row.addView(code,new LinearLayout.LayoutParams(dp(58),-1));TextView name=text(v.name,13,INK);name.setMaxLines(2);name.setEllipsize(TextUtils.TruncateAt.END);row.addView(name,new LinearLayout.LayoutParams(0,-2,1));TextView eta=text(v.eta.length()>0?v.eta:"GPS",compact?20:24,INK);eta.setGravity(Gravity.RIGHT);row.addView(eta,new LinearLayout.LayoutParams(dp(83),-2));bottomRows.addView(row,new LinearLayout.LayoutParams(-1,dp(compact?52:60)));row.setOnClickListener(new View.OnClickListener(){public void onClick(View view){if(v.hasPosition())map.center(v.lat,v.lon,15);}});}if(snapshot.rows.isEmpty()){TextView empty=text(snapshot.emptyMessage.length()>0?snapshot.emptyMessage:snapshot.message.length()>0?snapshot.message:"Bu sorguda şu an GPS konumlu araç yok.",13,MUTED);empty.setMaxLines(compact?1:2);empty.setEllipsize(TextUtils.TruncateAt.END);bottomRows.addView(empty);if(city==1&&!snapshot.busStops.isEmpty())bottomRows.addView(button("Hat durağı seç",false,new View.OnClickListener(){public void onClick(View v){chooseBusStop();}}),new LinearLayout.LayoutParams(-1,dp(44)));}}
 private void showResults(){if(snapshot==null){showText("Canlı takip","Bir otobüs durağı girip Başlat'a dokun.");return;}StringBuilder s=new StringBuilder();s.append(snapshot.source).append("\n\n");for(JourneyData.Vehicle v:snapshot.rows)s.append(v.line).append(" · ").append(v.name).append("\n").append(v.eta).append("\nSon kaynak konumu: ").append(v.sourceTime.length()>0?v.sourceTime:"Zaman belirtilmedi").append("\n\n");if(snapshot.emptyMessage.length()>0)s.append("\n").append(snapshot.emptyMessage).append("\n");if(snapshot.separateMapRows)s.append("\nHaritadaki hat GPS aracı: ").append(snapshot.positionCount()).append(". Bu araçların tümü seçilen durağa yaklaşan araç değildir.\n");if(snapshot.message.length()>0)s.append(snapshot.message);showText("Kaynak sonuçları",s.toString());}
