  ScrollView scroll=new ScrollView(this);body.addView(scroll,new LinearLayout.LayoutParams(-1,dp(compact?74:136)));railRows=new LinearLayout(this);railRows.setOrientation(1);railRows.setPadding(dp(16),0,dp(16),0);scroll.addView(railRows);renderRails();updateRailEstimate();if(resumed)handler.postDelayed(railTick,compact?5000:1000);
