 private void chooseRail(){final Dialog d=dialog("Metro hattı seç");LinearLayout content=(LinearLayout)d.findViewById(7201);ScrollView scroll=new ScrollView(this);LinearLayout list=new LinearLayout(this);list.setOrientation(1);scroll.addView(list);for(final JourneyData.RailLine line:rails){TextView row=text(line.id+" · "+line.name,14,INK);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(0,dp(8),0,dp(8));list.addView(row,new LinearLayout.LayoutParams(-1,dp(52)));row.setOnClickListener(new View.OnClickListener(){public void onClick(View v){d.dismiss();selectedRail=line;build();}});}if(rails.isEmpty())list.addView(text("Bu şehir için metro ağı eklenmedi.",14,MUTED));content.addView(scroll,new LinearLayout.LayoutParams(-1,dp(compact?250:350)));d.show();}
 private final Runnable railTick=new Runnable(){public void run(){if(resumed&&!destroyed&&screen==1){updateRailEstimate();handler.postDelayed(this,compact?5000:1000);}}};
 private void updateRailEstimate(){if(map==null||screen!=1)return;long now=System.currentTimeMillis();railEstimate=RailEstimator.estimate(this,city,selectedRail,rails,now);map.positions(railEstimate.trains,false);if(railStatus!=null){SimpleDateFormat clock=new SimpleDateFormat("HH:mm:ss",Locale.US);clock.setTimeZone(TimeZone.getTimeZone("GMT+03:00"));String label=selectedRail==null?"Hat seç":selectedRail.id+" · "+railEstimate.trains.size()+" tahmini tren · "+clock.format(new Date(now));railStatus.setText(label+"\n"+(railEstimate.trains.isEmpty()?"Modelde bu saatte tren yok veya saat verisi eksik.":"Trene dokun: yön ve hesaplama bilgisi."));}}
 private void renderRails(){railRows.removeAllViews();if(rails.isEmpty()){railRows.addView(text("Bu şehir için metro katmanı henüz eklenmedi.",14,MUTED));return;}if(selectedRail!=null){for(final JourneyData.Station station:selectedRail.stations){TextView name=text(station.name,14,INK);name.setGravity(Gravity.CENTER_VERTICAL);name.setPadding(dp(8),0,dp(8),0);railRows.addView(name,new LinearLayout.LayoutParams(-1,dp(46)));name.setOnClickListener(new View.OnClickListener(){public void onClick(View v){map.center(station.lat,station.lon,16);if(city==2&&selectedRail!=null&&selectedRail.id.equals("İZBAN"))showIzbanTimes(station.name);}});}return;}
 for(final JourneyData.RailLine line:rails){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);TextView id=text(line.id,18,Color.parseColor(line.color));row.addView(id,new LinearLayout.LayoutParams(dp(56),-2));LinearLayout names=new LinearLayout(this);names.setOrientation(1);TextView title=text(line.name,14,INK);title.setMaxLines(1);title.setEllipsize(TextUtils.TruncateAt.END);names.addView(title);names.addView(text(line.stations.size()+" istasyon",12,MUTED));row.addView(names,new LinearLayout.LayoutParams(0,-2,1));row.addView(text("›",22,MUTED));railRows.addView(row,new LinearLayout.LayoutParams(-1,dp(64)));row.setOnClickListener(new View.OnClickListener(){public void onClick(View v){selectedRail=line;ArrayList<JourneyData.RailLine> one=new ArrayList<JourneyData.RailLine>();one.add(line);map.lines(one);map.focus(line);renderRails();}});}}
 private void setAppearance(boolean dark){ThemeColors.setDark(this,dark);build();TransitWidget.renderAll(this);}
 private void settingsScreen(){ScrollView scroll=new ScrollView(this);body.addView(scroll,new LinearLayout.LayoutParams(-1,-1));LinearLayout panel=new LinearLayout(this);panel.setOrientation(1);panel.setPadding(dp(20),dp(8),dp(20),dp(20));scroll.addView(panel);panel.addView(text("Yolculuk ayarları",24,INK));panel.addView(button("Gizlilik ve kişisel veriler",false,new View.OnClickListener(){public void onClick(View v){showText("Gizlilik",LegalNotice.read(TransitActivity.this,"privacy.txt"));}}),new LinearLayout.LayoutParams(-1,dp(44)));panel.addView(button("Kullanım ve sorumluluk",false,new View.OnClickListener(){public void onClick(View v){showText("Kullanım ve sorumluluk",LegalNotice.read(TransitActivity.this,"terms.txt"));}}),new LinearLayout.LayoutParams(-1,dp(44)));TextView appearance=text("Görünüm",14,INK);appearance.setPadding(0,dp(20),0,dp(8));panel.addView(appearance);LinearLayout modes=new LinearLayout(this);Button light=button("Açık",!palette.dark,new View.OnClickListener(){public void onClick(View view){setAppearance(false);}}),dark=button("Koyu",palette.dark,new View.OnClickListener(){public void onClick(View view){setAppearance(true);}});light.setId(7601);dark.setId(7602);light.setContentDescription("Açık tema"+(palette.dark?"":", seçili"));dark.setContentDescription("Koyu tema"+(palette.dark?", seçili":""));LinearLayout.LayoutParams mode=new LinearLayout.LayoutParams(0,dp(44),1);mode.rightMargin=dp(8);modes.addView(light,mode);modes.addView(dark,new LinearLayout.LayoutParams(0,dp(44),1));panel.addView(modes);TextView info=text("Transit TR 1.4.0\n\nUygulama içi takip harita açıkken yenilenir. Widget kayıtları ekran açıkken yaklaşık dakikada bir sorgulanır. Konumlar belediye servislerinden, harita karoları OpenStreetMap'ten alınır. İETT durak dakikaları ve hat durakları Otobüsüm Anlık (otobusum.metkm.win) üzerinden sorgulanır. İETT açık SOAP servisi hat GPS kaynağıdır; aracı konum servisi yedek olarak kullanılır.\n\nMetro ayrı haritadadır. Tren işaretleri kalkış çizelgesi veya sefer sıklığından saate göre hesaplanan tahminlerdir; GPS değildir. Model düğmesi kaynak ve varsayımları gösterir.\n\nİzmir’de ESHOT hedef durağa süreyi sağlarsa dakika gösterilir. Yedek kaynak yalnız durak sayısı veriyorsa dakika üretilmez. Konya’da ATUS mobil servisi araç GPS’ini sağlar.\n\nGüvenli bağlantı: sertifika zinciri ve sunucu adı doğrulanır. Doğrulama hatasında bağlantı kurulmaz.\n\nHarita karoları ziyaret edilen görünüm için önbelleğe alınır. Toplu harita indirme yoktur.",14,MUTED);info.setPadding(0,dp(16),0,dp(20));panel.addView(info);panel.addView(button("Ankara saatlerini eşitle",false,new View.OnClickListener(){public void onClick(View v){if(egoSync!=null)egoSync.close();egoSync=new EgoSyncDialog(TransitActivity.this,face);egoSync.show();}}),new LinearLayout.LayoutParams(-1,dp(44)));panel.addView(button("OpenStreetMap lisansı",false,new View.OnClickListener(){public void onClick(View v){try{startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://www.openstreetmap.org/copyright")));}catch(Exception ignored){}}}),new LinearLayout.LayoutParams(-1,dp(44)));}
 private void showIzbanTimes(final String origin){try{
  java.io.InputStream in=getAssets().open("izban-stations.json");java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] buf=new byte[2048];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);in.close();final org.json.JSONArray stations=new org.json.JSONArray(new String(out.toByteArray(),"UTF-8"));final ArrayList<String> names=new ArrayList<String>();int found=-1;for(int i=0;i<stations.length();i++){org.json.JSONObject st=stations.getJSONObject(i);names.add(st.getString("IstasyonAdi"));if(origin.equals(st.getString("IstasyonAdi")))found=st.getInt("IstasyonId");}if(found<0){showText("İZBAN","İstasyon bulunamadı.");return;}final int from=found;
  final Dialog d=dialog(origin+" · İZBAN");LinearLayout content=(LinearLayout)d.findViewById(7201);content.addView(text("Varış istasyonunu seç. Gösterilen saatler planlıdır.",14,MUTED));final Spinner destination=new Spinner(this);destination.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_item,names));content.addView(destination,new LinearLayout.LayoutParams(-1,dp(48)));
  content.addView(button("Sefer saatlerini getir",true,new View.OnClickListener(){public void onClick(View v){try{final int to=stations.getJSONObject(destination.getSelectedItemPosition()).getInt("IstasyonId");if(to==from){showText("İZBAN","Farklı bir varış istasyonu seç.");return;}d.dismiss();final String destinationName=names.get(destination.getSelectedItemPosition());new Thread(new Runnable(){public void run(){String result;try{org.json.JSONArray times=new org.json.JSONArray(ApiHttp.get("https://openapi.izmir.bel.tr/api/izban/sefersaatleri/"+from+"/"+to));StringBuilder b=new StringBuilder("Planlı sefer saatleri · canlı araç konumu değildir\n\n");for(int i=0;i<times.length();i++){org.json.JSONObject t=times.getJSONObject(i);b.append(t.optString("HareketSaati")).append(" → ").append(t.optString("VarisSaati")).append("\n");}result=times.length()==0?"Bu istasyon çifti için sefer bulunamadı.":b.toString();}catch(Exception e){result="İZBAN saatleri alınamadı: "+e.getMessage();}final String message=result;handler.post(new Runnable(){public void run(){if(!destroyed)showText(origin+" → "+destinationName,message);}});}}).start();}catch(Exception e){showText("İZBAN","İstasyon seçilemedi.");}}}),new LinearLayout.LayoutParams(-1,dp(44)));d.show();
 }catch(Exception e){showText("İZBAN","İstasyon verisi okunamadı.");}}
 private void catalogScreen(){CatalogScreen.State state=catalogStates.get(Integer.valueOf(city));if(state==null){state=new CatalogScreen.State();catalogStates.put(Integer.valueOf(city),state);}catalog=new CatalogScreen(this,body,city,face,compact,state,new CatalogScreen.Navigation(){public void track(CatalogStore.Item item){stopTracking();String stop=item.kind==1?item.code:getPreferences(0).getString("track-stop:"+city,defaultStop()),line=item.kind==0?item.code.split("_")[0]:"";getPreferences(0).edit().putString("track-stop:"+city,stop).putString("track-line:"+city,line).putString("track-direction:"+city,"").commit();snapshot=null;screen=0;build();beginTracking();}public void point(CatalogStore.Item item){stopTracking();snapshot=null;screen=0;build();map.center(item.lat,item.lon,16);}public void route(CatalogStore.Item item){stopTracking();selectedCatalogRoute=item;screen=4;build();}public void rail(String code){stopTracking();selectedRail=null;try{for(JourneyData.RailLine line:MetroData.lines(TransitActivity.this,city))if(line.id.equalsIgnoreCase(code)){selectedRail=line;break;}}catch(Exception ignored){}screen=1;build();}});}
 private void routeScreen(){routeScreen=new RouteScreen(this,body,city,selectedCatalogRoute,face,compact,new RouteScreen.Navigation(){public void back(){screen=3;build();}public void stop(JourneyData.Station stop){stopTracking();getPreferences(0).edit().putString("track-stop:"+city,stop.code).putString("track-line:"+city,selectedCatalogRoute.code.split("_")[0]).putString("track-direction:"+city,"").commit();snapshot=null;screen=0;build();beginTracking();}public void line(CatalogStore.Item item){stopTracking();getPreferences(0).edit().putString("track-line:"+city,item.code.split("_")[0]).commit();snapshot=null;screen=0;build();beginTracking();}});}
 private void navigation(){LinearLayout nav=new LinearLayout(this);nav.setBackgroundColor(palette.surface);root.addView(nav,new LinearLayout.LayoutParams(-1,dp(56)));String[] names={"Otobüs","Metro","Katalog","Ayarlar"};final int[] destinations={0,1,3,2};for(int i=0;i<4;i++){final int target=destinations[i];boolean active=screen==target||screen==4&&target==3;TextView t=text(names[i],13,active?INK:MUTED);t.setGravity(Gravity.CENTER);{Drawable icon=new TransitNavDrawable(i,active?INK:MUTED);icon.setBounds(0,0,dp(24),dp(24));t.setCompoundDrawables(null,icon,null,null);t.setCompoundDrawablePadding(dp(3));}nav.addView(t,new LinearLayout.LayoutParams(0,-1,1));t.setOnClickListener(new View.OnClickListener(){public void onClick(View v){if(target!=screen){stopTracking();screen=target;selectedRail=null;build();}}});}}
 public void onBackPressed(){if(screen==4){screen=3;build();}else if(screen!=0){stopTracking();screen=0;selectedRail=null;build();}else super.onBackPressed();}
 protected void onResume(){super.onResume();resumed=true;if(routeScreen!=null)routeScreen.pause(false);if(map!=null)map.pause(false);if(tracking&&screen==0)handler.post(poll);if(screen==1)handler.post(railTick);}
 protected void onPause(){if(egoSync!=null)egoSync.close();if(routeScreen!=null)routeScreen.pause(true);if(catalog!=null)catalog.pause();resumed=false;handler.removeCallbacks(railTick);handler.removeCallbacks(poll);if(map!=null)map.pause(true);generation++;if(request!=null)request.interrupt();refreshing=false;super.onPause();}
 protected void onDestroy(){if(firstRunDialog!=null){firstRunDialog.dismiss();firstRunDialog=null;}if(routeScreen!=null){routeScreen.close();routeScreen=null;}if(catalog!=null){catalog.close();catalog=null;}destroyed=true;stopTracking();handler.removeCallbacksAndMessages(null);if(map!=null)map.close();super.onDestroy();}
